const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const source = body.update_id ? 'telegram' : (body.source ?? 'webhook');
const userId = body.message?.from?.id ?? body.callback_query?.from?.id ?? body.user_id ?? null;
const eventType = body.callback_query ? 'callback_query' : (body.message ? 'message' : (body.event_type ?? 'webhook'));
return [{json:{source,user_id:userId ? String(userId) : null,event_type:eventType,payload:body,headers,received_at:new Date().toISOString()}}];

const crypto = require('crypto');
const j = $json;
const rawEvent = j.payload?.update_id ?? j.payload?.callback_query?.id ?? j.payload?.message?.message_id ?? crypto.randomUUID();
const event_id = `${j.source}_${rawEvent}`;
const correlation_id = `COR-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
return [{json:{...j,event_id,correlation_id}}];
